F","handle":"merelle-xuanying-tay-hyk1nrz","nationality":"SGP","sail_number":"SGP 3511"},{"id":"f1293134-c948-4eef-b57f-8e8851feab28","name":"Riley Sullivan","gender":"M","handle":"riley-sullivan-08glscv","nationality":"USA","sail_number":"21745"},{"id":"e0d61d81-9b7f-45d3-a6fb-b78ff25b39dc","name":"Chen Wang Sun","gender":"M","handle":"chen-wang-sun","nationality":"MAC","sail_number":"MAC 20"}],"corrections":[{"ordinal":11,"resultId":"23c4a3f8-c1d9-45ac-a431-633d9c11ae21","previousSailorId":"6fcdc03f-6b56-4e08-aa6d-2cc6b0e9e675","sailorId":"20028ccf-ac2a-46af-b671-9e4cfba4d390","previousEntryLabel":"Sumire Sayawaki-Kogut","name":"Leopold Sayawaki-Kogut","sailOrBoardNumber":"SGP 710","ownershipBasis":"Official full name and historical sail identify a different existing sailor; the former owner is not an alias of this person. Correct this one result and its participant; retain the result ID. No identity consolidation."},{"ordinal":34,"resultId":"a1b3237e-c3c7-415d-bc7a-62e7be6eeab7","previousSailorId":"eb832e1f-2644-4453-9089-1598544bf217","sailorId":"c8f5d2b3-7e69-401b-8d44-2b7f9a1e5c32","previousEntryLabel":"Jonas Tan Kia Jeng","name":"Jonas Tan Yi Jun","sailOrBoardNumber":"SGP 3481","ownershipBasis":"Official full name and historical sail identify a different existing sailor; the former owner is not an alias of this person. Correct this one result and its participant; retain the result ID. No identity consolidation."},{"ordinal":55,"resultId":"0adcec9c-c05a-4677-ac64-f4a777e7e12d","previousSailorId":"2bef1064-0ac4-4ff0-80e0-c3d6e96979e7","sailorId":"a0084e06-8de6-4b1e-bbb6-4bb5d3918150","previousEntryLabel":"Tan Herng Yee","name":"Tan Yee Xuen","sailOrBoardNumber":"SGP 3001","ownershipBasis":"Official full name and historical sail identify a different existing sailor; the former owner is not an alias of this person. Correct this one result and its participant; retain the result ID. No identity consolidation."}]}'::jsonb;
 g regattas%rowtype; r jsonb; v_p jsonb; e jsonb; a regatta_results%rowtype;
 replay boolean; old_profiles text; profile_ids uuid[]; actual jsonb; target uuid;
begin
 select * into strict g from regattas where id=(m#>>'{sheet,id}')::uuid for update;
 if g.slug<>m#>>'{sheet,slug}' or g.boat_class<>'Optimist' or g.division<>m#>>'{sheet,division}' or g.date<>(m#>>'{event,startDate}')::date or g.entry_type<>'individual' or g.status<>'published' then raise exception 'Sheet identity or lifecycle changed'; end if;
 select exists(select 1 from admin_change_log where source='official-history-event-cleanup-2026-10-17' and action='results.import_official_history' and entity_id=g.id) into replay;
 select array_agg(distinct sid) into profile_ids from(select (x->>'id')::uuid sid from jsonb_array_elements(m->'profilePreflight') x union select (x->>'sailor_id')::uuid from jsonb_array_elements(m->'beforeResults') x) ids;
 perform 1 from sailors where id=any(profile_ids) order by id for update;
 perform 1 from regatta_results where regatta_id=g.id order by id for update;
 perform 1 from regatta_result_participants where regatta_result_id in(select id from regatta_results where regatta_id=g.id) order by id for update;
 select md5(jsonb_agg(to_jsonb(s) order by s.id)::text) into old_profiles from sailors s where id=any(profile_ids);
 for v_p in select value from jsonb_array_elements(m->'profilePreflight') loop
  if not exists(select 1 from sailors s where s.id=(v_p->>'id')::uuid and jsonb_build_object('id',s.id,'name',s.name,'handle',s.handle,'sail_number',s.sail_number,'gender',s.gender,'nationality',s.nationality)=v_p) then raise exception 'Identity preflight changed: %',v_p->>'name'; end if;
 end loop;
 if not replay then
  select jsonb_agg(jsonb_build_object('id',x.id,'sailor_id',x.sailor_id,'regatta_id',x.regatta_id,'rank',x.rank,'total_score',x.total_score,'nett_score',x.nett_score,'is_dns',x.is_dns,'is_overseas_commitment',x.is_overseas_commitment,'entry_type',x.entry_type) order by x.id) into actual from regatta_results x where regatta_id=g.id;
  if actual is distinct from m->'beforeResults' then raise exception 'Result ownership/inventory changed since preflight'; end if;
  select jsonb_agg(jsonb_build_object('id',x.id,'regatta_result_id',x.regatta_result_id,'sailor_id',x.sailor_id,'source_name',x.source_name,'display_order',x.display_order,'role',x.role,'ranking_credit',x.ranking_credit) order by x.id) into actual from regatta_result_participants x join regatta_results rr on rr.id=x.regatta_result_id where rr.regatta_id=g.id;
  if actual is distinct from m->'beforeParticipants' then raise exception 'Participant ownership/inventory changed since preflight'; end if;
  if exists(select 1 from regatta_race_results x join regatta_results rr on rr.id=x.regatta_result_id where rr.regatta_id=g.id) then raise exception 'Existing race data needs reconciliation before mutation'; end if;
  if exists(select 1 from jsonb_array_elements(m->'beforeParticipants') historypart where historypart->>'role'<>'solo' or (historypart->>'display_order')::int<>1) then raise exception 'Individual sheet has conflicting participant structure'; end if;
  if (select count(distinct x->>'sailorId') from jsonb_array_elements(m->'results') x)<>jsonb_array_length(m->'results') then raise exception 'Separate individual entries cannot share an identity'; end if;
  insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source)
   values('results.import_official_history','regatta',g.id,m#>>'{sheet,name}','Reconciled historical summary entries with the visually reviewed official PDF; retained result IDs and all source race data.',jsonb_build_object('beforeSheet',to_jsonb(g),'beforeResults',(select jsonb_agg(to_jsonb(x)) from regatta_results x where regatta_id=g.id),'beforeParticipants',(select jsonb_agg(to_jsonb(p)) from regatta_result_participants p join regatta_results x on x.id=p.regatta_result_id where x.regatta_id=g.id),'beforeRaces','[]'::jsonb,'source',m->'officialSource','identityCorrections',m->'corrections','newProfiles',m->'newProfiles','entryCount',jsonb_array_length(m->'results'),'raceCount',m#>'{sheet,raceCount}'),'official-history-event-cleanup-2026-10-17');
  for v_p in select value from jsonb_array_elements(m->'newProfiles') loop
   if exists(select 1 from sailors s where (s.id=(v_p->>'id')::uuid or s.handle=v_p->>'handle' or lower(s.name)=lower(v_p->>'name')) and not (s.id=(v_p->>'id')::uuid and s.name=v_p->>'name' and s.handle=v_p->>'handle' and s.sail_number=v_p->>'sail_number' and s.gender=v_p->>'gender' and s.nationality is not distinct from v_p->>'nationality')) then raise exception 'New sailor identity conflict: %',v_p->>'name'; end if;
   insert into sailors(id,name,handle,sail_number,gender,nationality,club) values((v_p->>'id')::uuid,v_p->>'name',v_p->>'handle',v_p->>'sail_number',v_p->>'gender',v_p->>'nationality',v_p->>'club') on conflict(id) do nothing;
  end loop;
  -- This alias is explicitly corrected only in the SYSC Silver transaction, after user identity confirmation.
  if m#>>'{sheet,slug}'='sysc-silver-mar-23-2023-03-11' then
   select (x->>'id')::uuid into strict target from jsonb_array_elements(m->'newProfiles') x where x->>'name'='Tan Jia Kai';
   perform 1 from sailor_aliases where id='bf3c2f02-3664-4d7f-a99b-d98d30a23fc0' for update;
   if not exists(select 1 from sailor_aliases where id='bf3c2f02-3664-4d7f-a99b-d98d30a23fc0' and alias_name='Tan Jia Kai' and sailor_id='c882b08f-4572-49d3-9c02-7365adabba38') then raise exception 'Tan Jia Kai alias preflight changed'; end if;
   insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source) select 'sailors.correct_alias','sailor',target,'Tan Jia Kai','User confirmed Tan Jia Kai and Hillary Kai Hui Tan are different sailors; corrected the alias and one historical entry.',jsonb_build_object('beforeAlias',to_jsonb(x),'newSailorId',target,'otherHillaryResults',10,'scope','All 11 Hillary-owned entries reviewed; only the 2023 SYSC entry is identified as Tan Jia Kai by the supplied source. No other entries reassigned.'),'official-history-event-cleanup-2026-10-17' from sailor_aliases x where id='bf3c2f02-3664-4d7f-a99b-d98d30a23fc0';
   update sailor_aliases set sailor_id=target where id='bf3c2f02-3664-4d7f-a99b-d98d30a23fc0';
   insert into admin_change_log(action,entity_type,entity_id,entity_label,summary,details,source) values('sailors.duplicates.keep_separate','sailor',target,'Tan Jia Kai / Hillary Kai Hui Tan','Confirmed these are different sailors.',jsonb_build_object('pairKey',least(target,'c882b08f-4572-49d3-9c02-7365adabba38'::uuid)::text||'|'||greatest(target,'c882b08f-4572-49d3-9c02-7365adabba38'::uuid)::text,'aId',least(target,'c882b08f-4572-49d3-9c02-7365adabba38'::uuid),'bId',greatest(target,'c882b08f-4572-49d3-9c02-7365adabba38'::uuid),'aName',(select name from sailors where id=least(target,'c882b08f-4572-49d3-9c02-7365adabba38'::uuid)),'bName',(select name from sailors where id=greatest(target,'c882b08f-4572-49d3-9c02-7365adabba38'::uuid)),'reason','User confirmed different sailors on 17 October 2026. Official SYSC 2023 Silver lists Tan Jia Kai, male, sail 73; Hillary is a separate female sailor.'),'official-history-event-cleanup-2026-10-17');
  end if;
  e=m->'event';
  if (e->>'existing')::boolean then
   if not exists(select 1 from regatta_events where id=(e->>'id')::uuid and slug=e->>'slug' and start_date=(e->>'startDate')::date and end_date=(e->>'endDate')::date) then raise exception 'Canonical parent identity changed'; end if;
  else
   if exists(select 1 from regatta_events where (slug=e->>'slug' or id=(e->>'id')::uuid) and not(id=(e->>'id')::uuid and slug=e->>'slug' and start_date=(e->>'startDate')::date and end_date=(e->>'endDate')::date)) then raise exception 'Parent event collision'; end if;
   insert into regatta_events(id,name,slug,start_date,end_date,venue,organizer,classes,counts_for_ranking) values((e->>'id')::uuid,e->>'name',e->>'slug',(e->>'startDate')::date,(e->>'endDate')::date,g.venue,g.organizer,case when e->>'slug'='csc-optimist-championships-2024' then '["Optimist Gold"]'::jsonb else '["Optimist Gold","Optimist Silver"]'::jsonb end,true) on conflict(id) do nothing;
  end if;
  if g.event_id is not null and g.event_id<>(e->>'id')::uuid then raise exception 'Sheet already belongs to another parent'; end if;
  update regattas set name=m#>>'{sheet,name}',event_id=(e->>'id')::uuid,end_date=(e->>'endDate')::date,race_count=(m#>>'{sheet,raceCount}')::int,total_fleet_size=(m#>>'{sheet,totalFleetSize}')::int,official_results_url=m#>>'{officialSource,url}',official_results_source_name=m#>>'{officialSource,title}',reviewed_at=now(),updated_at=now() where id=g.id;
  for r in select value from jsonb_array_elements(m->'results') loop
   if exists(select 1 from regatta_results where regatta_id=g.id and sailor_id=(r->>'sailorId')::uuid and id<>(r->>'resultId')::uuid) then raise exception 'Conflicting individual entries: %',r->>'name'; end if;
   select * into a from regatta_results where id=(r->>'resultId')::uuid;
   if a.id is not null and (a.regatta_id<>g.id or a.sailor_id<>coalesce((r->>'previousSailorId')::uuid,(r->>'sailorId')::uuid)) then raise exception 'Explicit result ownership differs'; end if;
   insert into regatta_results(id,sailor_id,regatta_id,entry_label,entry_sail_number,entry_type,rank,total_score,nett_score,gender,nationality,is_dns,is_overseas_commitment,official_url,evidence_url,evidence_name,evidence_type,evidence_notes,verification_status,verified_at)
    values((r->>'resultId')::uuid,(r->>'sailorId')::uuid,g.id,r->>'name',r->>'sailOrBoardNumber','individual',(r->>'rank')::int,(r->>'grossScore')::real,(r->>'nettScore')::real,r->>'gender',r->>'nationality',false,false,m#>>'{officialSource,url}',m#>>'{officialSource,url}',m#>>'{officialSource,title}','pdf',r->>'evidenceNotes','verified',now())
    on conflict(id) do update set sailor_id=excluded.sailor_id,entry_label=excluded.entry_label,entry_sail_number=excluded.entry_sail_number,entry_type=excluded.entry_type,rank=excluded.rank,total_score=excluded.total_score,nett_score=excluded.nett_score,gender=excluded.gender,nationality=excluded.nationality,birth_year=case when regatta_results.sailor_id<>excluded.sailor_id then (select extract(year from dob)::int from sailors where id=excluded.sailor_id) else regatta_results.birth_year end,is_dns=false,is_overseas_commitment=false,official_url=excluded.official_url,evidence_url=excluded.evidence_url,evidence_name=excluded.evidence_name,evidence_type=excluded.evidence_type,evidence_notes=concat_ws(E'
',nullif(regatta_results.evidence_notes,''),excluded.evidence_notes),verification_status='verified',verified_at=now(),updated_at=now();
   insert into regatta_result_participants(id,regatta_result_id,sailor_id,source_name,display_order,role,match_status,ranking_credit) values((r->>'participantId')::uuid,(r->>'resultId')::uuid,(r->>'sailorId')::uuid,r->>'name',1,'solo','matched',true)
    on conflict(id) do update set sailor_id=excluded.sailor_id,source_name=excluded.source_name,role='solo',match_status='matched',ranking_credit=true,updated_at=now();
   insert into regatta_race_results(regatta_result_id,race_number,score,scoring_code,discarded,raw_value) select (r->>'resultId')::uuid,(x->>'raceNumber')::int,(x->>'score')::real,x->>'code',(x->>'discarded')::boolean,x->>'raw' from jsonb_array_elements(r->'races') x;
  end loop;
 end if;
 -- Verify desired values on first execution and every replay, without mutating an already completed import.
 if (select count(*) from regatta_results where regatta_id=g.id)<>jsonb_array_length(m->'results') then raise exception 'Final entry count differs'; end if;
 if not exists(select 1 from regattas where id=g.id and official_results_url=m#>>'{officialSource,url}' and official_results_source_name=m#>>'{officialSource,title}' and race_count=(m#>>'{sheet,raceCount}')::int and total_fleet_size=(m#>>'{sheet,totalFleetSize}')::int and event_id=(m#>>'{event,id}')::uuid and counts_for_ranking=true and status='published') then raise exception 'Final sheet metadata differs'; end if;
 for r in select value from jsonb_array_elements(m->'results') loop
  if not exists(select 1 from regatta_results where id=(r->>'resultId')::uuid and sailor_id=(r->>'sailorId')::uuid and regatta_id=g.id and entry_label=r->>'name' and entry_sail_number=r->>'sailOrBoardNumber' and rank=(r->>'rank')::int and total_score=(r->>'grossScore')::real and nett_score=(r->>'nettScore')::real and gender=r->>'gender' and official_url=m#>>'{officialSource,url}' and evidence_url=m#>>'{officialSource,url}' and evidence_name=m#>>'{officialSource,title}' and verification_status='verified') then raise exception 'Result verification failed: %',r->>'name'; end if;
  if (select count(*) from regatta_result_participants where regatta_result_id=(r->>'resultId')::uuid)<>1 or not exists(select 1 from regatta_result_participants where id=(r->>'participantId')::uuid and regatta_result_id=(r->>'resultId')::uuid and sailor_id=(r->>'sailorId')::uuid and source_name=r->>'name' and display_order=1 and role='solo' and ranking_credit=true) then raise exception 'Participant verification failed'; end if;
  if (select count(*) from regatta_race_results where regatta_result_id=(r->>'resultId')::uuid)<>jsonb_array_length(r->'races') then raise exception 'Race count differs'; end if;
  for v_p in select value from jsonb_array_elements(r->'races') loop
   if not exists(select 1 from regatta_race_results where regatta_result_id=(r->>'resultId')::uuid and race_number=(v_p->>'raceNumber')::int and score=(v_p->>'score')::real and scoring_code is not distinct from v_p->>'code' and discarded=(v_p->>'discarded')::boolean and raw_value=v_p->>'raw') then raise exception 'Race code, discard, or score differs'; end if;
  end loop;
  if not exists(select 1 from regatta_race_results where regatta_result_id=(r->>'resultId')::uuid group by regatta_result_id having abs(sum(score)-(r->>'grossScore')::numeric)<0.001 and abs(sum(case when discarded then 0 else score end)-(r->>'nettScore')::numeric)<0.001) then raise exception 'Gross/net arithmetic failed'; end if;
 end loop;
 if old_profiles is distinct from (select md5(jsonb_agg(to_jsonb(s) order by s.id)::text) from sailors s where id=any(profile_ids)) then raise exception 'Existing athlete profile fields changed'; end if;
end $import$;
commit;
